+	async reload(nameOrPath: string): Promise<PluginStatusRecord[]> {
+		const matches = this.match(nameOrPath);
+		for (const entry of matches) {
+			entry.fingerprint = undefined;
+			entry.lastError = undefined;
+			entry.errorCount = 0;
+			entry.timeoutCount = 0;
