+
+export interface PluginSessionLoadResult {
+	extensions: AgentExtension[];
+	pluginPaths: string[];
+	failures: PluginInitializationFailure[];
+	warnings: PluginInitializationWarning[];
+	issues: SessionPluginIssue[];
+	/**
