+		for (const generation of entry.retired) {
+			this.recordFailure(entry, generation, "uncaught", error, {
+				fatal: true,
+				messagePrefix: `${label}: `,
+			});
+		}
+		this.recordFailure(entry, entry.current, "uncaught", error, {
+			fatal: true,
+			messagePrefix: `${label}: `,
+		});
