+						if (!this.isUsable(instance)) return;
+						const sessionContext = {
+							...(input.setupContext?.session ?? {}),
+							...(ctx.session ?? {}),
+						};
+						const base = { ...(input.setupContext ?? {}), ...ctx };
+						const setupContext: PluginSetupContext = {
+							...base,
+							session:
