+									? sessionContext
+									: undefined,
+							automation: outsidePluginScope(base.automation),
+							logger: outsidePluginScope(base.logger),
+							telemetry: outsidePluginScope(base.telemetry),
+							cwd: input.cwd ?? ctx.cwd,
+							emitEvent,
+							onDispose: (cleanup) => {
