+									instance.disposers.push(cleanup);
+								}
+							},
+						};
+						await this.runSetup(
+							entry,
+							instance,
+							(bufferedApi) => originalSetup(bufferedApi, setupContext),
+							api,
+							scope,
+							input,
+							timeouts,
+						);
+					}
+				: undefined,
+		};
+		return wrapped;
+	}
+
+	private async runSetup(
+		entry: PluginEntry,
+		instance: PluginInstance,
+		invoke: (api: SetupApi) => void | Promise<void>,
