+		// registers something invalid, contributes nothing instead of leaving
+		// the session with half a plugin.
+		const bufferedApi: SetupApi = {
+			registerTool: (tool) => {
+				pending.tools.push(tool);
+			},
+			registerCommand: (command) => {
+				pending.commands.push(command);
+			},
+			registerRule: (rule) => {
